const raw = JSON.parse($json.raw_response_json);
const triggerCtx = $('When Executed by Another Workflow').first().json;

const text =
  raw.candidates?.[0]?.content?.parts
    ?.map(part => part.text || '')
    .join('') || '';

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error(`Gemini did not return valid JSON. Raw text: ${text.slice(0, 1000)}`);
}

const usage = raw.usageMetadata || {};

return [{
  json: {
    output: parsed,

    ts: new Date().toISOString(),
    execution_id: String(triggerCtx.parent_execution_id || ''),
    workflow_id: String(triggerCtx.parent_workflow_id || ''),
    workflow_name: triggerCtx.parent_workflow_name || '',

    solution: triggerCtx.solution || '',
    environment: triggerCtx.environment || '',
    provider: 'gemini',
    provider_account: triggerCtx.provider_account || '',
    cost_center: triggerCtx.cost_center || '',
    credential_name: triggerCtx.credential_name || '',
    model: triggerCtx.model || '',
    node_name: triggerCtx.node_name || '',
    customer_id: triggerCtx.customer_id || '',
    status: 'success',
    request_id: raw.responseId || raw.id || '',
    error_message: '',

    input_tokens: Number(usage.promptTokenCount || 0),
    output_tokens: Number(usage.candidatesTokenCount || 0),
    cache_tokens: Number(usage.cachedContentTokenCount || 0),
    thought_tokens: Number(usage.thoughtsTokenCount || 0),
    total_tokens: Number(usage.totalTokenCount || 0),

    estimated_cost: 0,
    currency: triggerCtx.currency || 'USD',
    prompt_chars: (triggerCtx.prompt_text || '').length,
    response_chars: text.length,
    is_streaming: false,
    cache_hit: Number(usage.cachedContentTokenCount || 0) > 0,
    metadata_json: JSON.stringify({
      usageMetadata: usage,
      promptFeedback: raw.promptFeedback || null,
      finishReason: raw.candidates?.[0]?.finishReason || null,
    }),
  }
}];

const row = $json;

// Keep this central and reusable.
// Keys must match exactly the model value your workflows store.
const PRICE_BOOK = {
  gemini: {
    "gemini-2.5-flash-lite": {
      inputPerMillion: 0.10,
      outputPerMillion: 0.40,
      cachedInputPerMillion: 0.025,
      includeThoughtTokensInOutput: true,
    },
    "gemini-2.5-flash-lite-preview-09-2025": {
      inputPerMillion: 0.10,
      outputPerMillion: 0.40,
      cachedInputPerMillion: 0.025,
      includeThoughtTokensInOutput: true,
    },
    "gemini-2.5-flash": {
      inputPerMillion: 0.30,
      outputPerMillion: 2.50,
      cachedInputPerMillion: 0.03,
      includeThoughtTokensInOutput: true,
    },
    "gemini-2.5-flash-preview-09-2025": {
      inputPerMillion: 0.30,
      outputPerMillion: 2.50,
      cachedInputPerMillion: 0.03,
      includeThoughtTokensInOutput: true,
    },
  },

  openai: {
    "gpt-5.4": {
      inputPerMillion: 2.50,
      outputPerMillion: 15.00,
      cachedInputPerMillion: 0.25,
      includeThoughtTokensInOutput: false,
    },
    "gpt-5.4 mini": {
      inputPerMillion: 0.75,
      outputPerMillion: 4.50,
      cachedInputPerMillion: 0.075,
      includeThoughtTokensInOutput: false,
    },
    "gpt-5.5": {
      inputPerMillion: 5.00,
      outputPerMillion: 30.00,
      cachedInputPerMillion: 0.50,
      includeThoughtTokensInOutput: false,
    },
    "gpt-5": {
      inputPerMillion: 1.25,
      outputPerMillion: 10.00,
      cachedInputPerMillion: 0.125,
      includeThoughtTokensInOutput: false,
    },
    "gpt-5-mini": {
      inputPerMillion: 0.25,
      outputPerMillion: 2.00,
      cachedInputPerMillion: 0.025,
      includeThoughtTokensInOutput: false,
    },
    "gpt-5-nano": {
      inputPerMillion: 0.05,
      outputPerMillion: 0.40,
      cachedInputPerMillion: 0.005,
      includeThoughtTokensInOutput: false,
    },
    "gpt-4.1": {
      inputPerMillion: 2.00,
      outputPerMillion: 8.00,
      cachedInputPerMillion: 0.50,
      includeThoughtTokensInOutput: false,
    },
    "gpt-4.1-mini": {
      inputPerMillion: 0.40,
      outputPerMillion: 1.60,
