      cachedInputPerMillion: 0.025,
      includeThoughtTokensInOutput: false,
    },
    "gpt-4o": {
      inputPerMillion: 2.50,
      outputPerMillion: 10.00,
      cachedInputPerMillion: 1.25,
      includeThoughtTokensInOutput: false,
    },
    "gpt-4o-mini": {
      inputPerMillion: 0.15,
      outputPerMillion: 0.60,
      cachedInputPerMillion: 0.075,
      includeThoughtTokensInOutput: false,
    },
    "o3": {
