      includeThoughtTokensInOutput: false,
    },
    "o4-mini": {
      inputPerMillion: 1.10,
      outputPerMillion: 4.40,
      cachedInputPerMillion: 0.275,
      includeThoughtTokensInOutput: false,
    },
  },
};

function normalizeProvider(value) {
  return String(value || "").trim().toLowerCase();
}

function normalizeModel(value) {
  const model = String(value || "").trim();

  // Normalize dated OpenAI model variants, e.g. gpt-4.1-mini-2025-04-14 -> gpt-4.1-mini
  return model.replace(/-\d{4}-\d{2}-\d{2}$/, "");
}

const provider = normalizeProvider(row.provider);
const model = normalizeModel(row.model);

const providerBook = PRICE_BOOK[provider] || {};
const pricing = providerBook[model];

if (!pricing) {
  return [{
    json: {
      ...row,
      estimated_cost: null,
      price_lookup_status: "missing_model_pricing",
      price_lookup_key: `${provider}:${model}`,
    }
  }];
}

const inputTokens = Number(row.input_tokens || 0);
const outputTokens = Number(row.output_tokens || 0);
const cacheTokens = Number(row.cache_tokens || 0);
const thoughtTokens = Number(row.thought_tokens || 0);

// Cached tokens are already included inside input_tokens.
// Do not charge them twice.
const billableCachedInputTokens = Math.min(cacheTokens, inputTokens);
const billableRegularInputTokens = Math.max(inputTokens - billableCachedInputTokens, 0);

const billableOutputTokens = pricing.includeThoughtTokensInOutput
  ? outputTokens + thoughtTokens
  : outputTokens;

const inputCost =
  (billableRegularInputTokens / 1_000_000) * Number(pricing.inputPerMillion || 0);

const cacheCost =
  (billableCachedInputTokens / 1_000_000) * Number(pricing.cachedInputPerMillion || 0);

const outputCost =
  (billableOutputTokens / 1_000_000) * Number(pricing.outputPerMillion || 0);

const estimatedCost = Number((inputCost + cacheCost + outputCost).toFixed(8));

return [{
  json: {
    ...row,
    estimated_cost: estimatedCost,
    price_lookup_status: "ok",
    price_lookup_key: `${provider}:${model}`,
  }
}];
